-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"قيمة الأمانة في بيئة العمل","passage":"في مثال أصلي لاحظ موظف أن تقريرًا محاسبيًا يحتوي رقمًا غير صحيح، فأبلغ المسؤول ودون التصحيح بدل تركه ليمر سريعًا. يرتبط صدق العمل بالتحقق وتحمل المسؤولية. لا ينسب المثال إلى نص «من أخلاق العمل في الإسلام» أو إلى حديث غير موثق.","prompt":"أي سلوك يعبّر عن الأمانة؟","correct":"إبلاغ المسؤول وتصحيح الرقم","w1":"إخفاء الخطأ","w2":"حذف الملف","w3":"ترك الرقم كما هو","practice":"اكتب فقرة تبين خلقًا مهنيًا بقصة وسبب ونتيجة، ثم استخرج شاهدًا حقيقيًا من النص المدرسي بعد قراءته."},{"n":2,"skill":"النعت وعلاقته بالمنعوت","passage":"في «اطلعتُ على خطةٍ واضحةٍ» كلمة «واضحةٍ» نعت مجرور تابع لـ«خطةٍ» في الإعراب والتنكير، وفي «الخططُ الواضحةُ مفيدةٌ» يتبع النعت المنعوت الجمع غير العاقل بصيغة مفرد مؤنث مناسبة.","prompt":"ما إعراب «واضحةٍ» في الجملة الأولى؟","correct":"نعت مجرور","w1":"خبر مرفوع","w2":"مفعول به","w3":"فاعل","practice":"اكتب أربع جمل فيها نعوت مرفوعة ومنصوبة ومجرورة، ثم وضح المطابقة مع المنعوت."},{"n":3,"skill":"بناء الفقرة الحجاجية بالدليل","passage":"الأطروحة «ينبغي اختبار الأنظمة الجديدة قبل تعميمها» تحتاج سببًا ودليلًا ومثالًا واعتراضًا وجوابًا. يمكن الاحتجاج بأن الاختبار المبكر يكشف المشكلات، لكن لا يصح اختلاق نسب حوادث أو أرقام بلا مصدر.","prompt":"ما الذي يجعل الأطروحة أكثر إقناعًا؟","correct":"حجة مع دليل محدد","w1":"تكرار الادعاء","w2":"حذف الاعتراض","w3":"الاعتماد على شعار","practice":"اكتب فقرة حجاجية من ثماني جمل حول التقنية في الإدارة تشمل رأيًا وسببًا ومثالًا واعتراضًا وردًا."},{"n":4,"skill":"التعاون في مشروع مشترك","passage":"قسم فريق تصميم المهام بين جمع المتطلبات ورسم الواجهة واختبار النموذج، ثم راجع كل عضو نتيجة الآخر. اكتشف الفريق خطأ مبكرًا لأن التعاون شمل التحقق والتواصل لا مجرد توزيع الأسماء في التقرير. المثال أصلي وليس نص القراءة.","prompt":"كيف ساعد التعاون في تجنب الخطأ؟","correct":"المراجعة المتبادلة بعد توزيع الأدوار","w1":"عمل عضو واحد فقط","w2":"ترك النتائج بلا تدقيق","w3":"إلغاء التواصل","practice":"صمم جدول أدوار لفريق من أربعة أفراد ومؤشرًا يتحقق به كل عضو من جودة الإنجاز."},{"n":5,"skill":"البدل المطابق","passage":"«قدمَ المهندسُ خالدٌ المقترحَ» يمكن إعراب «خالدٌ» بدلًا مطابقًا من «المهندسُ» إذا دل الاسمان على الشخص نفسه؛ ويتبع البدل المبدل منه في الإعراب. و«قابلتُ المهندسَ خالدًا» تتغير فيه حركة البدل إلى النصب.","prompt":"ما إعراب «خالدٌ» في المثال الأول؟","correct":"بدل مطابق مرفوع","w1":"خبر","w2":"مفعول به منصوب","w3":"تمييز","practice":"اكتب ثلاث جمل تتضمن بدلًا مطابقًا في سياقات إدارية، ثم أعرب البدل والمبدل منه."},{"n":6,"skill":"منافع الشراكة ومخاطرها","passage":"اقترحت مؤسستان مشاركة قاعة تدريب وأجهزة؛ أشارت الأولى إلى خفض التكلفة، بينما نبهت الثانية إلى ضرورة تحديد المسؤوليات والخصوصية وجدول الاستخدام. توصل الطرفان إلى اتفاق مبدئي مشروط بمعايير واضحة.","prompt":"ما التحفظ الأساسي على الشراكة؟","correct":"ضرورة تحديد المسؤوليات والخصوصية","w1":"وجود قاعة تدريب","w2":"إمكان التعاون","w3":"اختيار موعد اجتماع","practice":"اكتب حوارًا من ثماني مداخلات يوازن بين منفعتين ومخاطرتين لشراكة بين شركتين."},{"n":7,"skill":"العناية بالأرض بحجج عملية","passage":"اقترح فريق في مدرسة قياس استهلاك المياه قبل وبعد تركيب مرشدات تدفق مناسبة، وميّز التوقع من النتيجة التي تحتاج تجربة. يشجع المثال احترام الموارد ويُظهر أن حماية الأرض تحتاج بيانات وسلوكًا، لكنه لا يمثل النص المدرسي «الأرض هي الحياة».","prompt":"ما الفعل الذي يجعل أثر الترشيد قابلاً للتحقق؟","correct":"قياس الاستهلاك قبل وبعد","w1":"الاكتفاء بشعار","w2":"إلغاء التجربة","w3":"ترك الصيانة","practice":"استخرج من النص الأصلي فكرة وشاهدًا، ثم اكتب مقترحًا بيئيًا بمؤشر قياس وتحفظ علمي."},{"n":8,"skill":"التقنية بين الفائدة والضرر","passage":"رأى طالب أن تطبيقات الهاتف تسهّل تنظيم الدراسة، واعترض زميله بأن التنبيهات قد تقطع التركيز وأن مشاركة البيانات تحتاج احتياطًا. اتفقا على إيقاف الإشعارات أثناء التعلم ومراجعة أذونات التطبيقات، دون تعميم أن التقنية نافعة أو ضارة دائمًا.","prompt":"ما القيد الذي وضعه الطالبان لاستخدام التطبيقات؟","correct":"التحكم في الإشعارات والأذونات","w1":"تجاهل الخصوصية","w2":"ترك الدراسة","w3":"منع الحوار","practice":"نظّم مناظرة قصيرة عن التقنية والشباب بحجتين مؤيدتين وحجتين ناقدتين ورد متزن."},{"n":9,"skill":"قراءة التراث ومصدر المعلومات","passage":"يحمل اسم «مسار اللؤلؤ» صلة بتراث البحرين، لكن تفاصيل النص المدرسي تحتاج الرجوع إلى المصدر قبل وصف الأشخاص والأحداث. في نص مستقل يشرح مرشد لطلاب كيف تُحفظ الأدوات التراثية وتُوثق قصص أصحابها، ويدعوهم إلى تسجيل مصادر المعلومات.","prompt":"ماذا طلب المرشد من الطلاب؟","correct":"توثيق مصادر المعلومات","w1":"اختلاق القصص","w2":"إهمال الأدوات","w3":"منع الأسئلة","practice":"اكتب فقرة عن موقع تراثي بحريني بملاحظات شخصية وحقائق موثقة تفصل بينهما."},{"n":10,"skill":"التوكيد اللفظي والمعنوي","passage":"«نجح نجح المشروعُ» يتضمن توكيدًا لفظيًا بتكرار الفعل، و«حضر الموظفون كلُّهم» يتضمن توكيدًا معنويًا مرفوعًا تابعًا للمؤكد. ينبغي مراعاة الضمير المتصل في بعض ألفاظ التوكيد المعنوي وعدم عد كل تكرار عارض توكيدًا.","prompt":"ما نوع التوكيد في «حضر الموظفون كلهم»؟","correct":"توكيد معنوي","w1":"بدل","w2":"حال","w3":"خبر","practice":"أنشئ مثالين لكل من التوكيد اللفظي والمعنوي، ثم أعرب التوكيد المعنوي."},{"n":11,"skill":"الأطروحة المتوازنة والدليل","passage":"يمكن صياغة أطروحة تقول «تسهم أنظمة الأرشفة الإلكترونية في سرعة الوصول للملفات عند حسن تصميمها». لا تعني الجملة أن النظام يمنع الخطأ مطلقًا؛ ويحتاج الدفاع عنها إلى مثال أو تجربة موثقة مع مناقشة المخاطر.","prompt":"ما التحفظ المنطقي على أطروحة الأرشفة؟","correct":"تتوقف الفائدة على التصميم والاستخدام","w1":"لا توجد مخاطر أبدًا","w2":"لا يمكن قياس الوقت","w3":"كل الأوراق مفقودة","practice":"اكتب أطروحة عن الإدارة الرقمية بدليل وسبب واعتراض ورد معلل، دون اختلاق إحصاءات."},{"n":12,"skill":"فهم النص الأدبي بلا نسبة أبيات","passage":"يتطلب نص «أغنية من ألبا» الاطلاع على الكلمات الأصلية قبل تحديد عاطفة الشاعر أو صورته. نموذج نثري مستقل: «يرى العامل ضوء المصنع عند الفجر، فيتذكر جهد زملائه ودقة ما صنعوه». يوحي بالفخر بالعمل، وليس مقتبسًا من النص.","prompt":"ما العاطفة الأقرب إلى النموذج الأصلي؟","correct":"الفخر بالعمل المشترك","w1":"اللامبالاة","w2":"الشماتة","w3":"الخوف من التعلم","practice":"بعد مراجعة النص المدرسي، استخرج شاهدًا لغويًا صحيحًا يدل على عاطفة أو صورة، وناقشه."},{"n":13,"skill":"نماذج بحرينية والتوثيق","passage":"في حوار تربوي أصلي وصف طالب نجاح مبادرة بحرينية عامة دون تسمية أشخاص أو ادعاء إنجازات غير موثقة، وطلب زميله أن يبحثا عن سيرة منشورة رسمية قبل إعداد العرض. يركز التدريب على الشواهد والمثابرة والتوثيق.","prompt":"ما الخطوة التي تسبق نسبة إنجاز لشخص؟","correct":"التحقق من مصدر موثوق","w1":"نقل إشاعة","w2":"اختلاق سيرة","w3":"حذف الاسم","practice":"أعد حوارًا عن نموذج بحريني ملهم باستخدام مصدر موثق، ثم ميّز المعلومة من رأيك الشخصي."},{"n":14,"skill":"صور المكان في قصيدة موثقة","passage":"تحليل قصيدة «إلى الزلاق» يحتاج النص الأصلي للتحقق من الأبيات والاستعارات وموقف الشاعر. في مثال نثري مستقل «كلما مررت بالشاطئ عادت إليّ ذكريات طفولتي» يظهر الحنين، لكن الجملة ليست من القصيدة.","prompt":"ما العاطفة الظاهرة في المثال المستقل؟","correct":"الحنين إلى المكان","w1":"اللامبالاة","w2":"التعجب من آلة","w3":"الفخر بامتحان","practice":"اختر بيتًا حقيقيًا من القصيدة بعد توثيق النص واشرح أثر صورة المكان في عاطفة الشاعر."},{"n":15,"skill":"الأمر والنهي وأثرهما","passage":"«احفظْ نسخةً من الملف» أمر للتوجيه، و«لا تُهمِلْ مراجعةَ البيانات» نهي بـ«لا» الناهية، والفعل «تهملْ» مضارع مجزوم بالسكون. يختلف الأمر والنهي من حيث الصيغة والمطلوب تنفيذه.","prompt":"ما نوع «لا» في «لا تهمل مراجعة البيانات»؟","correct":"لا الناهية الجازمة","w1":"لا النافية","w2":"حرف عطف","w3":"أداة نداء","practice":"اكتب تعليمات آمنة في العمل تتضمن خمسة أوامر وخمسة نواهٍ، ثم اضبط الأفعال."},{"n":16,"skill":"الوفاء للوطن في المسؤولية اليومية","passage":"اتفق طلاب على إنشاء دليل رقمي لفرص التطوع في محيطهم، على أن يراجعوا تفاصيل الجهات وطرق التواصل قبل نشرها، ويحترموا خصوصية المشاركين. يعكس الحوار خدمة الوطن ضمن عمل مفيد بدل الاكتفاء بالمديح.","prompt":"ما الشرط اللازم قبل نشر دليل التطوع؟","correct":"التحقق من المعلومات وحماية الخصوصية","w1":"نشر بيانات خاصة","w2":"تجاهل الجهات","w3":"كتابة مواعيد غير صحيحة","practice":"أعد حوارًا من ثماني مداخلات عن الانتماء للوطن يتضمن نشاطًا عمليًا ومعيار أثر."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=11
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='44c1dfd0-27ec-41b6-bee7-a4576a582ad5'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 813 — اللغة العربية للمسار الإداري والتكنولوجي - الهندسي' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_ADMIN_ENG_G11_T1_ARAB813_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.correct,r.w3) ELSE jsonb_build_array(r.w1,r.w2,r.w3,r.correct) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_ADMIN_ENG_G11_T1_ARAB813_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_ADMIN_ENG_G11_T1_ARAB813_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_ADMIN_ENG_G11_T1_ARAB813_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;